[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ClipCast — One video is worth a thousand words</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --primary: #6366f1;
      --primary-dark: #4f46e5;
      --primary-light: #818cf8;
      --accent: #a855f7;
      --dark: #292a2e;
      --gray-600: #52525b;
      --gray-400: #a1a1aa;
      --gray-200: #e4e4e7;
      --gray-100: #f4f4f5;
      --gray-50: #fafafa;
      --white: #ffffff;
      --success: #10b981;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
    }
    body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif; color: var(--dark); line-height: 1.6; background: var(--white); -webkit-font-smoothing: antialiased; }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 24px; border-radius: var(--radius); font-weight: 600; font-size: 15px; cursor: pointer; border: none; transition: all 0.2s; }
    .btn-primary { background: var(--primary); color: var(--white); }
    .btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
    .btn-secondary { background: var(--white); color: var(--dark); border: 1px solid var(--gray-200); }
    .btn-secondary:hover { border-color: var(--primary); color: var(--primary); }
    .btn-lg { padding: 16px 32px; font-size: 16px; }
    .section-label { display: inline-block; padding: 6px 14px; background: rgba(99,102,241,0.1); color: var(--primary); font-size: 13px; font-weight: 600; border-radius: 100px; margin-bottom: 16px; }
    .section-title { font-size: clamp(32px, 5vw, 48px); font-weight: 800; line-height: 1.15; margin-bottom: 16px; }
    .section-subtitle { font-size: 18px; color: var(--gray-600); max-width: 600px; }
    .text-center { text-align: center; }
    .mx-auto { margin-left: auto; margin-right: auto; }

    /* Nav */
    nav { position: fixed; top: 0; left: 0; right: 0; z-index: 100; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); border-bottom: 1px solid var(--gray-100); }
    nav .container { display: flex; align-items: center; justify-content: space-between; height: 64px; }
    .nav-logo { font-size: 20px; font-weight: 800; color: var(--primary); }
    .nav-logo span { color: var(--dark); }
    .nav-links { display: flex; align-items: center; gap: 32px; }
    .nav-links a { font-size: 14px; font-weight: 500; color: var(--gray-600); transition: color 0.2s; }
    .nav-links a:hover { color: var(--primary); }
    .nav-actions { display: flex; align-items: center; gap: 12px; }
    .nav-actions .btn { padding: 10px 20px; font-size: 14px; }

    /* Hero */
    .hero { padding: 160px 0 80px; background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%); }
    .hero-content { max-width: 800px; margin: 0 auto; text-align: center; }
    .hero h1 { font-size: clamp(40px, 6vw, 64px); font-weight: 800; line-height: 1.1; margin-bottom: 24px; background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
    .hero p { font-size: 20px; color: var(--gray-600); margin-bottom: 32px; max-width: 600px; margin-left: auto; margin-right: auto; }
    .hero-buttons { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
    .hero-stats { display: flex; justify-content: center; gap: 48px; margin-top: 48px; padding-top: 48px; border-top: 1px solid var(--gray-200); }
    .hero-stat { text-align: center; }
    .hero-stat-num { font-size: 28px; font-weight: 800; color: var(--primary); }
    .hero-stat-label { font-size: 14px; color: var(--gray-600); }

    /* Logo Bar */
    .logo-bar { padding: 48px 0; background: var(--white); border-bottom: 1px solid var(--gray-100); }
    .logo-bar p { text-align: center; font-size: 14px; color: var(--gray-400); margin-bottom: 24px; }
    .logo-bar-logos { display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap; opacity: 0.6; }
    .logo-bar-logos span { font-size: 18px; font-weight: 700; color: var(--gray-600); }

    /* Feature Highlight (AI Bug Reports) */
    .feature-highlight { padding: 96px 0; background: var(--white); }
    .feature-highlight-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .feature-highlight-badge { background: linear-gradient(135deg, var(--primary), var(--accent)); color: var(--white); font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 100px; display: inline-block; margin-bottom: 16px; }
    .feature-highlight h2 { font-size: 36px; font-weight: 800; margin-bottom: 16px; }
    .feature-highlight p { color: var(--gray-600); margin-bottom: 24px; font-size: 16px; line-height: 1.7; }
    .feature-highlight-img { background: linear-gradient(135deg, var(--gray-100), var(--gray-50)); border-radius: var(--radius-xl); padding: 48px; aspect-ratio: 4/3; display: flex; align-items: center; justify-content: center; }
    .feature-highlight-img-inner { background: var(--white); border-radius: var(--radius-lg); padding: 32px; box-shadow: var(--shadow-lg); width: 100%; }
    .mock-jira { background: var(--gray-50); border-radius: var(--radius); padding: 20px; border: 1px solid var(--gray-200); }
    .mock-jira-header { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
    .mock-jira-icon { width: 32px; height: 32px; background: #0052cc; border-radius: 6px; }
    .mock-jira-title { font-weight: 600; font-size: 14px; }
    .mock-jira-meta { font-size: 12px; color: var(--gray-400); }
    .mock-jira-body { font-size: 13px; color: var(--gray-600); line-height: 1.6; }
    .mock-jira-tags { display: flex; gap: 8px; margin-top: 16px; }
    .mock-tag { background: rgba(99,102,241,0.1); color: var(--primary); font-size: 11px; padding: 4px 10px; border-radius: 100px; font-weight: 500; }

    /* Screen Recorder */
    .screen-recorder { padding: 96px 0; background: var(--gray-50); }
    .screen-recorder-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .screen-recorder-content h2 { font-size: 36px; font-weight: 800; margin-bottom: 16px; }
    .screen-recorder-content p { color: var(--gray-600); margin-bottom: 32px; font-size: 16px; line-height: 1.7; }
    .screen-recorder-features { display: flex; flex-direction: column; gap: 16px; margin-bottom: 32px; }
    .screen-recorder-feature { display: flex; align-items: center; gap: 12px; font-size: 15px; font-weight: 500; }
    .screen-recorder-feature i { width: 24px; height: 24px; background: rgba(16,185,129,0.1); color: var(--success); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 12px; }
    .screen-recorder-img { background: var(--white); border-radius: var(--radius-xl); padding: 32px; box-shadow: var(--shadow-xl); }
    .recorder-mock { background: var(--gray-900); border-radius: var(--radius-lg); padding: 24px; color: var(--white); }
    .recorder-mock-header { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; }
    .recorder-dot { width: 12px; height: 12px; border-radius: 50%; }
    .recorder-dot.red { background: #ff5f57; }
    .recorder-dot.yellow { background: #febc2e; }
    .recorder-dot.green { background: #28c840; }
    .recorder-mock-screen { background: var(--gray-600); border-radius: var(--radius); height: 200px; display: flex; align-items: center; justify-content: center; margin-bottom: 16px; }
    .recorder-controls { display: flex; justify-content: center; gap: 16px; }
    .recorder-btn { width: 48px; height: 48px; border-radius: 50%; background: var(--primary); display: flex; align-items: center; justify-content: center; }

    /* Video Editor */
    .video-editor { padding: 96px 0; background: var(--white); }
    .video-editor-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .video-editor-content h2 { font-size: 36px; font-weight: 800; margin-bottom: 24px; }
    .video-editor-list { list-style: none; display: flex; flex-direction: column; gap: 20px; }
    .video-editor-list li { display: flex; gap: 16px; }
    .video-editor-list .icon { width: 40px; height: 40px; background: linear-gradient(135deg, var(--primary), var(--accent)); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; color: var(--white); flex-shrink: 0; }
    .video-editor-list h4 { font-weight: 600; margin-bottom: 4px; }
    .video-editor-list p { font-size: 14px; color: var(--gray-600); }
    .video-editor-img { background: linear-gradient(135deg, var(--primary), var(--accent)); border-radius: var(--radius-xl); padding: 32px; }
    .video-editor-mock { background: var(--white); border-radius: var(--radius-lg); padding: 24px; box-shadow: var(--shadow-lg); }
    .video-timeline { height: 8px; background: var(--gray-200); border-radius: 4px; margin: 20px 0; position: relative; }
    .video-timeline-progress { position: absolute; left: 0; top: 0; height: 100%; width: 35%; background: var(--primary); border-radius: 4px; }
    .video-clips { display: flex; gap: 8px; }
    .video-clip { flex: 1; height: 48px; background: var(--gray-100); border-radius: 8px; }
    .video-clip:nth-child(1) { background: var(--primary); opacity: 0.8; }
    .video-clip:nth-child(2) { background: var(--primary-light); opacity: 0.6; }
    .video-tools { display: flex; justify-content: center; gap: 12px; margin-top: 16px; }
    .video-tool { width: 36px; height: 36px; background: var(--gray-100); border-radius: 8px; display: flex; align-items: center; justify-content: center; }

    /* Integrations */
    .integrations { padding: 96px 0; background: var(--gray-50); }
    .integrations-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 48px; }
    .integration-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; text-align: center; border: 1px solid var(--gray-100); transition: all 0.3s; }
    .integration-card:hover { border-color: var(--primary); transform: translateY(-4px); box-shadow: var(--shadow-lg); }
    .integration-icon { width: 56px; height: 56px; background: var(--gray-100); border-radius: var(--radius); margin: 0 auto 16px; display: flex; align-items: center; justify-content: center; font-size: 24px; }
    .integration-card h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
    .integration-card p { font-size: 13px; color: var(--gray-400); }

    /* Engagement */
    .engagement { padding: 96px 0; background: var(--white); }
    .engagement-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; margin-top: 48px; }
    .engagement-card { background: var(--gray-50); border-radius: var(--radius-lg); padding: 32px; }
    .engagement-card h4 { font-size: 18px; font-weight: 700; margin-bottom: 12px; }
    .engagement-card p { font-size: 14px; color: var(--gray-600); line-height: 1.6; }

    /* Security */
    .security { padding: 96px 0; background: var(--gray-900); color: var(--white); }
    .security .section-title { color: var(--white); }
    .security .section-subtitle { color: var(--gray-400); }
    .security-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-top: 48px; }
    .security-card { background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); border-radius: var(--radius-lg); padding: 32px; }
    .security-card i { font-size: 32px; margin-bottom: 16px; color: var(--primary-light); }
    .security-card h4 { font-size: 16px; font-weight: 600; margin-bottom: 8px; }
    .security-card p { font-size: 14px; color: var(--gray-400); line-height: 1.5; }

    /* Use Cases */
    .use-cases { padding: 96px 0; background: var(--white); }
    .use-cases-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 48px; }
    .use-case-card { background: var(--gray-50); border-radius: var(--radius-lg); padding: 32px; text-align: center; transition: all 0.3s; cursor: pointer; }
    .use-case-card:hover { background: var(--primary); color: var(--white); transform: translateY(-4px); box-shadow: var(--shadow-xl); }
    .use-case-card:hover p { color: rgba(255,255,255,0.8); }
    .use-case-icon { width: 64px; height: 64px; background: var(--white); border-radius: var(--radius-lg); margin: 0 auto 20px; display: flex; align-items: center; justify-content: center; font-size: 28px; }
    .use-case-card h4 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .use-case-card p { font-size: 14px; color: var(--gray-600); line-height: 1.5; transition: color 0.3s; }

    /* Features Grid */
    .features-grid { padding: 96px 0; background: var(--gray-50); }
    .features-grid-outer { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
    .feature-card { background: var(--white); border-radius: var(--radius-lg); padding: 28px; border: 1px solid var(--gray-100); transition: all 0.3s; }
    .feature-card:hover { border-color: var(--primary); box-shadow: var(--shadow-md); }
    .feature-card i { font-size: 24px; color: var(--primary); margin-bottom: 16px; }
    .feature-card h4 { font-size: 16px; font-weight: 600; margin-bottom: 8px; }
    .feature-card p { font-size: 14px; color: var(--gray-600); line-height: 1.5; }

    /* Blog */
    .blog { padding: 96px 0; background: var(--white); }
    .blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; margin-top: 48px; }
    .blog-card { background: var(--gray-50); border-radius: var(--radius-lg); overflow: hidden; transition: all 0.3s; }
    .blog-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
    .blog-img { height: 180px; background: linear-gradient(135deg, var(--primary), var(--accent)); display: flex; align-items: center; justify-content: center; color: var(--white); font-size: 48px; }
    .blog-content { padding: 24px; }
    .blog-content h4 { font-size: 17px; font-weight: 700; margin-bottom: 12px; line-height: 1.4; }
    .blog-content p { font-size: 14px; color: var(--gray-600); line-height: 1.6; margin-bottom: 16px; }
    .blog-link { color: var(--primary); font-size: 14px; font-weight: 600; display: inline-flex; align-items: center; gap: 6px; }

    /* Enterprise CTA */
    .enterprise-cta { padding: 96px 0; background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%); color: var(--white); }
    .enterprise-cta .container { text-align: center; }
    .enterprise-cta h2 { font-size: 36px; font-weight: 800; margin-bottom: 16px; }
    .enterprise-cta p { font-size: 18px; opacity: 0.9; margin-bottom: 32px; max-width: 500px; margin-left: auto; margin-right: auto; }
    .btn-white { background: var(--white); color: var(--primary); }
    .btn-white:hover { background: var(--gray-100); transform: translateY(-1px); }

    /* Testimonials */
    .testimonials { padding: 96px 0; background: var(--gray-50); }
    .testimonials-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
    .testimonial-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; box-shadow: var(--shadow-sm); }
    .testimonial-card blockquote { font-size: 15px; line-height: 1.7; color: var(--gray-600); margin-bottom: 24px; font-style: italic; }
    .testimonial-author { display: flex; align-items: center; gap: 12px; }
    .testimonial-avatar { width: 44px; height: 44px; background: linear-gradient(135deg, var(--primary), var(--accent)); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--white); font-weight: 700; font-size: 16px; }
    .testimonial-info h5 { font-size: 14px; font-weight: 600; }
    .testimonial-info p { font-size: 13px; color: var(--gray-400); }

    /* CTA Banner */
    .cta-banner { padding: 80px 0; background: var(--white); }
    .cta-banner .container { text-align: center; }
    .cta-banner h2 { font-size: 32px; font-weight: 800; margin-bottom: 8px; }
    .cta-banner p { font-size: 16px; color: var(--gray-400); margin-bottom: 32px; }

    /* Footer */
    footer { background: var(--gray-900); color: var(--white); padding: 80px 0 40px; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(4, 1fr); gap: 48px; margin-bottom: 48px; }
    .footer-brand p { font-size: 14px; color: var(--gray-400); margin-top: 16px; line-height: 1.6; }
    .footer-col h5 { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 20px; }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 12px; }
    .footer-col a { font-size: 14px; color: var(--gray-400); transition: color 0.2s; }
    .footer-col a:hover { color: var(--white); }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 32px; display: flex; justify-content: space-between; align-items: center; font-size: 13px; color: var(--gray-400); }
    .footer-legal { display: flex; gap: 24px; }

    /* Cookie Banner */
    .cookie-banner { position: fixed; bottom: 0; left: 0; right: 0; background: var(--white); border-top: 1px solid var(--gray-200); padding: 20px 0; z-index: 1000; box-shadow: 0 -4px 20px rgba(0,0,0,0.1); display: none; }
    .cookie-banner.show { display: block; }
    .cookie-content { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
    .cookie-text { font-size: 14px; color: var(--gray-600); flex: 1; min-width: 300px; }
    .cookie-text a { color: var(--primary); text-decoration: underline; }
    .cookie-actions { display: flex; gap: 12px; align-items: center; }
    .cookie-actions .btn { padding: 10px 20px; font-size: 14px; }

    /* Cookie Modal */
    .cookie-modal { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); z-index: 1001; display: none; align-items: center; justify-content: center; }
    .cookie-modal.show { display: flex; }
    .cookie-modal-content { background: var(--white); border-radius: var(--radius-xl); padding: 32px; max-width: 500px; width: 90%; max-height: 80vh; overflow-y: auto; }
    .cookie-modal h3 { font-size: 20px; font-weight: 700; margin-bottom: 8px; }
    .cookie-modal > p { font-size: 14px; color: var(--gray-600); margin-bottom: 24px; }
    .cookie-category { border: 1px solid var(--gray-200); border-radius: var(--radius); padding: 20px; margin-bottom: 16px; }
    .cookie-category-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
    .cookie-category h4 { font-size: 15px; font-weight: 600; }
    .cookie-category p { font-size: 13px; color: var(--gray-600); }
    .toggle-switch { width: 44px; height: 24px; background: var(--gray-200); border-radius: 12px; position: relative; cursor: pointer; transition: background 0.2s; }
    .toggle-switch.active { background: var(--primary); }
    .toggle-switch::after { content: ''; position: absolute; top: 2px; left: 2px; width: 20px; height: 20px; background: var(--white); border-radius: 50%; transition: transform 0.2s; box-shadow: var(--shadow-sm); }
    .toggle-switch.active::after { transform: translateX(20px); }
    .cookie-modal-actions { display: flex; gap: 12px; margin-top: 24px; }
    .cookie-modal-actions .btn { flex: 1; }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .hero { padding: 120px 0 60px; }
      .hero-stats { flex-direction: column; gap: 24px; }
      .feature-highlight-grid, .screen-recorder-grid, .video-editor-grid { grid-template-columns: 1fr; }
      .integrations-grid { grid-template-columns: repeat(2, 1fr); }
      .security-grid { grid-template-columns: repeat(2, 1fr); }
      .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
      .features-grid-outer { grid-template-columns: repeat(2, 1fr); }
      .engagement-grid { grid-template-columns: 1fr; }
      .testimonials-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .cookie-content { flex-direction: column; text-align: center; }
    }
  </style>
</head>
<body>
  <!-- Navigation -->
  <nav>
    <div class="container">
      <a href="index.html" class="nav-logo">Clip<span>Cast</span></a>
      <div class="nav-links">
        <a href="enterprise.html">Enterprise</a>
        <a href="pricing.html">Pricing</a>
        <a href="#">Solutions</a>
        <a href="#">Resources</a>
      </div>
      <div class="nav-actions">
        <a href="login.html" class="btn btn-secondary">Sign In</a>
        <a href="signup.html" class="btn btn-primary">Get Started for free</a>
      </div>
    </div>
  </nav>

  <!-- Hero -->
  <section class="hero">
    <div class="container">
      <div class="hero-content">
        <h1>One video is worth a thousand words</h1>
        <p>Easily record and share AI-powered video messages with your teammates and customers to supercharge productivity</p>
        <div class="hero-buttons">
          <a href="signup.html" class="btn btn-primary btn-lg">Get ClipCast for free</a>
          <a href="#" class="btn btn-secondary btn-lg">Install Chrome Extension</a>
        </div>
        <div class="hero-stats">
          <div class="hero-stat">
            <div class="hero-stat-num">2M+</div>
            <div class="hero-stat-label">Active users</div>
          </div>
          <div class="hero-stat">
            <div class="hero-stat-num">400K+</div>
            <div class="hero-stat-label">Companies</div>
          </div>
          <div class="hero-stat">
            <div class="hero-stat-num">50+</div>
            <div class="hero-stat-label">Languages</div>
          </div>
