  <script>
    let isAnnual = false;
    let expanded = false;

    function toggleBilling() {
      isAnnual = !isAnnual;
      document.getElementById('billingToggle').classList.toggle('active', isAnnual);
      document.getElementById('monthlyLabel').classList.toggle('active', !isAnnual);
      document.getElementById('annualLabel').classList.toggle('active', isAnnual);

      const amounts = document.querySelectorAll('.amount[data-monthly]');
      amounts.forEach(el => {
        el.textContent = isAnnual ? el.dataset.annual : el.dataset.monthly;
      });

      const annualNotes = document.querySelectorAll('.annual-note');
      annualNotes.forEach(el => {
        el.style.display = isAnnual ? 'block' : 'none';
      });
    }

    function updateTeamSize(value) {
      document.getElementById('teamSizeValue').textContent = value;
    }

    function toggleExpandAll() {
      expanded = !expanded;
      const hiddenRows = document.querySelectorAll('.hidden-rows');
      hiddenRows.forEach(row => {
        row.classList.toggle('show', expanded);
      });
      document.getElementById('expandText').textContent = expanded ? 'Hide all features' : 'See all features';
    }

    function toggleFaq(button) {
      const item = button.parentElement;
      const wasOpen = item.classList.contains('open');

      document.querySelectorAll('.faq-item').forEach(faq => {
        faq.classList.remove('open');
      });

      if (!wasOpen) {
        item.classList.add('open');
      }
    }
